const getCharlieActionSafetySnapshot = `-- name: GetCharlieActionSafetySnapshot :one
WITH current_receipt AS (
    SELECT current.id, current.created_at FROM charlie_action_receipts current
    WHERE current.charlie_action_id = $7
), prior_receipts AS (
    SELECT r.id, r.connection_id, r.session_id, r.charlie_action_id, r.turn_id, r.capability, r.effect, r.argument_digest, r.arguments_encrypted, r.authorization_hash, r.resource_digest, r.fencing_epoch, r.product_idempotency_key, r.state, r.attempt, r.lease_owner, r.lease_expires_at, r.result_digest, r.result_status, r.result_encrypted, r.audit_correlation_id, r.dispatched_at, r.verified_at, r.auto_budget_reserved, r.safety_policy_revision, r.created_at, r.updated_at FROM charlie_action_receipts r
    WHERE r.session_id = $8
      AND r.charlie_action_id <> $7
)
SELECT
    NOT EXISTS (
        SELECT 1 FROM prior_receipts r
        LEFT JOIN current_receipt c ON true
        WHERE r.state IN ('claimed', 'dispatched', 'verifying', 'ambiguous')
          AND (c.id IS NULL OR r.created_at < c.created_at OR (r.created_at = c.created_at AND r.id::text < c.id::text))
    ) AS incident_clear,
    NOT EXISTS (
        SELECT 1 FROM prior_receipts r
        WHERE r.capability = $1
          AND r.resource_digest = $2
          AND r.state IN ('dispatched', 'verifying', 'ambiguous', 'succeeded', 'failed')
          AND r.updated_at > now() - make_interval(secs => $3::integer)
    ) AS cooldown_clear,
    NOT EXISTS (
        SELECT 1 FROM prior_receipts r WHERE r.state IN ('failed', 'ambiguous')
    ) AS circuit_closed,
    (SELECT count(*) FROM prior_receipts r WHERE r.auto_budget_reserved) < $4::integer AS incident_budget_available,
    (SELECT count(*) FROM prior_receipts r
       WHERE r.auto_budget_reserved
         AND r.updated_at > now() - make_interval(secs => $5::integer)
    ) < $6::integer AS window_budget_available
`

type GetCharlieActionSafetySnapshotParams struct {
	CapabilityArg         string    `json:"capability_arg"`
	ResourceDigestArg     string    `json:"resource_digest_arg"`
	CooldownSeconds       int32     `json:"cooldown_seconds"`
	MaxActionsPerIncident int32     `json:"max_actions_per_incident"`
	BudgetWindowSeconds   int32     `json:"budget_window_seconds"`
	MaxActionsPerWindow   int32     `json:"max_actions_per_window"`
	ActionIDArg           string    `json:"action_id_arg"`
	SessionIDArg          uuid.UUID `json:"session_id_arg"`
}

type GetCharlieActionSafetySnapshotRow struct {
	IncidentClear           bool `json:"incident_clear"`
	CooldownClear           bool `json:"cooldown_clear"`
	CircuitClosed           bool `json:"circuit_closed"`
	IncidentBudgetAvailable bool `json:"incident_budget_available"`
	WindowBudgetAvailable   bool `json:"window_budget_available"`
}

func (q *Queries) GetCharlieActionSafetySnapshot(ctx context.Context, arg GetCharlieActionSafetySnapshotParams) (GetCharlieActionSafetySnapshotRow, error) {
	row := q.db.QueryRow(ctx, getCharlieActionSafetySnapshot,
		arg.CapabilityArg,
		arg.ResourceDigestArg,
		arg.CooldownSeconds,
		arg.MaxActionsPerIncident,
		arg.BudgetWindowSeconds,
		arg.MaxActionsPerWindow,
		arg.ActionIDArg,
		arg.SessionIDArg,
	)
	var i GetCharlieActionSafetySnapshotRow
	err := row.Scan(
		&i.IncidentClear,
		&i.CooldownClear,
		&i.CircuitClosed,
		&i.IncidentBudgetAvailable,
		&i.WindowBudgetAvailable,
	)
	return i, err
}

