const retryDeadCharlieTriggerEventWithOutbox = `-- name: RetryDeadCharlieTriggerEventWithOutbox :one
WITH source AS (
    SELECT e.id, e.rule_id, e.retry_of_event_id, e.source, e.event_type, e.resource_type, e.resource_id, e.fingerprint, e.summary_metadata, e.state, e.session_id, e.repeat_count, e.first_occurred_at, e.last_occurred_at, e.origin_resource_ref, e.origin_event_ref, e.attempt_count, e.next_attempt_at, e.last_error_code, e.dead_lettered_at, e.created_at, e.updated_at
    FROM charlie_trigger_events e
    JOIN charlie_trigger_rules r ON r.id = e.rule_id
    WHERE e.id = $1
      AND e.state = 'dead'
      AND r.connection_id = $2
), event AS (
    INSERT INTO charlie_trigger_events (
        id, rule_id, retry_of_event_id, source, event_type, resource_type,
        resource_id, fingerprint, summary_metadata, state, session_id,
        repeat_count, first_occurred_at, last_occurred_at,
        origin_resource_ref, origin_event_ref, attempt_count, next_attempt_at,
        last_error_code, dead_lettered_at
    )
    SELECT
        $3, rule_id, id, source, event_type, resource_type,
        resource_id, fingerprint, summary_metadata, 'pending', NULL,
        repeat_count, first_occurred_at, last_occurred_at,
        origin_resource_ref, origin_event_ref, 0, now(), '', NULL
    FROM source
    ON CONFLICT (id) DO UPDATE
    SET updated_at = charlie_trigger_events.updated_at
    WHERE charlie_trigger_events.retry_of_event_id = EXCLUDED.retry_of_event_id
      AND charlie_trigger_events.rule_id = EXCLUDED.rule_id
      AND charlie_trigger_events.fingerprint = EXCLUDED.fingerprint
    RETURNING id, rule_id, retry_of_event_id, source, event_type, resource_type, resource_id, fingerprint, summary_metadata, state, session_id, repeat_count, first_occurred_at, last_occurred_at, origin_resource_ref, origin_event_ref, attempt_count, next_attempt_at, last_error_code, dead_lettered_at, created_at, updated_at
), outbox AS (
    INSERT INTO task_outbox (
        dedupe_key, task_type, payload, queue_name, max_retry, timeout_seconds,
        unique_seconds, max_delivery_attempts, next_attempt_at
    )
    SELECT
        'charlie-trigger:' || id::text,
        'charlie:trigger_dispatch',
        convert_to(jsonb_build_object('event_id', id::text)::text, 'UTF8'),
        'tunnel', 8, 60, 1800, 20, next_attempt_at
    FROM event
    ON CONFLICT (dedupe_key) WHERE dedupe_key IS NOT NULL DO UPDATE SET
        payload = EXCLUDED.payload,
        status = CASE WHEN task_outbox.status = 'delivered' THEN task_outbox.status ELSE 'pending' END,
        attempt_count = CASE WHEN task_outbox.status = 'delivered' THEN task_outbox.attempt_count ELSE 0 END,
        next_attempt_at = CASE WHEN task_outbox.status = 'delivered' THEN task_outbox.next_attempt_at ELSE EXCLUDED.next_attempt_at END,
        locked_until = NULL,
        last_error = CASE WHEN task_outbox.status = 'delivered' THEN task_outbox.last_error ELSE '' END,
        updated_at = now()
    RETURNING id
)
SELECT event.id, event.rule_id, event.retry_of_event_id, event.source, event.event_type, event.resource_type, event.resource_id, event.fingerprint, event.summary_metadata, event.state, event.session_id, event.repeat_count, event.first_occurred_at, event.last_occurred_at, event.origin_resource_ref, event.origin_event_ref, event.attempt_count, event.next_attempt_at, event.last_error_code, event.dead_lettered_at, event.created_at, event.updated_at FROM event CROSS JOIN outbox
`

